import './globals.css';
import type { Metadata } from 'next';
import { Inter } from 'next/font/google';

const inter = Inter({ subsets: ['latin'] });

export const metadata: Metadata = {
  title: 'EaseMize Chat',
  description: 'A modern chat interface',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className={inter.className}>
      <body className="min-h-screen bg-background text-text antialiased">{children}</body>
    </html>
  );
}

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

interface Message {
  id: string;
  content: string;
  role: 'user' | 'assistant';
  createdAt: Date;
}

export default function MessageList({ messages }: { messages: Message[] }) {
  if (messages.length === 0) {
    return <EmptyState />;
  }

  return (
    <div className="flex-1 overflow-y-auto p-4 space-y-4">
      {messages.map((message) => (
        <div key={message.id} className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div className={`max-w-[80%] px-4 py-2 rounded-lg ${message.role === 'user' ? 'bg-accent text-white' : 'bg-surface text-text'}`}>
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
              {message.content}
            </ReactMarkdown>
            <div className="text-xs text-textSecondary mt-1">
              {new Date(message.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

import { useState } from 'react';

interface PromptInputProps {
  onSubmit: (message: string) => Promise<void>;
  isLoading: boolean;
}

export default function PromptInput({ onSubmit, isLoading }: PromptInputProps) {
  const [inputValue, setInputValue] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isLoading) return;

    await onSubmit(inputValue);
    setInputValue('');
  };

  return (
    <form onSubmit={handleSubmit} className="flex flex-col p-4 border-t border-border gap-2">
      <textarea
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder="Type a message..."
        className="min-h-[60px] resize-none px-4 py-3 bg-surface border border-border rounded-lg text-text focus:outline-none focus:ring-2 focus:ring-accent focus:ring-offset-0 disabled:opacity-50"
        rows={1}
        disabled={isLoading}
      ></textarea>
      <button
        type="submit"
        disabled={isLoading || !inputValue.trim()}
        className="px-4 py-2 bg-accent hover:bg-accentHover text-white rounded-md font-medium transition-colors disabled:opacity-50 w-full"
      >
        {isLoading ? 'Sending...' : 'Send'}
      </button>
    </form>
  );
}

import ChatSidebar from "./ChatSidebar";
import MessageList from "./MessageList";
import PromptInput from "./PromptInput";
import { useState, useCallback, useRef } from "react";

interface Message {
  id: string;
  content: string;
  role: "user" | "assistant";
  createdAt: Date;
}

export default function ChatLayout() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const addMessage = useCallback(
    (content: string, role: Message["role"]) => {
      const newMessage: Message = {
        id: Math.random().toString(36).substr(2, 9),
        content,
        role,
        createdAt: new Date(),
      };
      setMessages((prev) => [...prev, newMessage]);
    },
    []
  );

  const handleUserSubmit = async (message: string) => {
    // Add user message
    addMessage(message, "user");
    setIsLoading(true);

    try {
      // Simulate streaming response
      await simulateStreamingResponse(addMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const simulateStreamingResponse = async (
    addMessageFn: (content: string, role: Message["role"]) => void
  ) => {
    // Simulate thinking delay
    await new Promise((resolve) => setTimeout(resolve, 500));

    // Streaming response in chunks
    const responseChunks = [
      "Hello! I'm ",
      "EaseMize, ",
      "your AI assistant. ",
      "How can I ",
      "help you today? ",
      "\n\n",
      "I can assist with ",
      "various tasks like ",
      "answering questions, ",
      "providing explanations, ",
      "or just chatting. ",
      "What would you like ",
      "to discuss?",
    ];

    let accumulatedResponse = "";
    for (const chunk of responseChunks) {
      // Simulate typing delay
      await new Promise((resolve) => setTimeout(resolve, 50 + Math.random() * 100));
      accumulatedResponse += chunk;
      // Update the last message with accumulated response
      setMessages((prev) => {
        if (prev.length === 0) return prev;
        const lastMessage = prev[prev.length - 1];
        if (lastMessage.role === "assistant") {
          // Replace the last assistant message
          const updatedMessages = [...prev];
          updatedMessages[updatedMessages.length - 1] = {
            ...lastMessage,
            content: accumulatedResponse,
          };
          return updatedMessages;
        } else {
          // Add new assistant message
          return [
            ...prev,
            {
              id: Math.random().toString(36).substr(2, 9),
              content: accumulatedResponse,
              role: "assistant",
              createdAt: new Date(),
            },
          ];
        }
      });
    }
  };

  return (
    <div className="flex h-[calc(100vh-4.5rem)]">
      <ChatSidebar />
      <div className="flex-1 flex flex-col">
        <div className="flex-1 overflow-hidden">
          <MessageList messages={messages} />
          <div ref={messagesEndRef} className="h-4" />
        </div>
        <PromptInput onSubmit={handleUserSubmit} isLoading={isLoading} />
      </div>
    </div>
  );
}

import ChatLayout from "@/components/ChatLayout";

export default function Page() {
  return (
    <main className="flex min-h-screen">
      <ChatLayout />
    </main>
  );
}

